-- =========================================================================
-- 11/1 가격 변경 바로잡기 (0046 후속) — 최종 가격표는 10/14 파일
--
-- 0046은 10/13 파일(30%·35%) 기준으로 만들어졌으나, 최종 확정본은 '주문서양식_딜러가격
-- 35% (2026.10.14)'이다. 두 파일은 상품 334개 중 279개의 소비자가(MAP)가 다르다
-- (예: 600097 119,000 → 129,000원). 소비자가만 맞추면 앱이 30%/35% 등급별 딜러가를
-- 알아서 계산하므로 등급별 수정은 필요 없다.
--   - 아래 값은 0046에서 넣은 가격과 10/14 파일 가격이 다른 276개 + 601067(SKU 바로잡기 반영),
--     신규 러기지 택 2종(600989/600990)이다. 가격이 같은 상품은 건드리지 않는다.
--   - PRO IV 12종(고정 25% 할인가)의 소비자가는 10/14 파일도 259,000원이라 바뀌지 않는다.
--   - 블랙프라이데이 프로모션 가격(PRO IV 141,900 / PRO V 283,900)은 영향 없다.
-- =========================================================================

-- 0) 되돌릴 수 있게 지금(0046 적용 후) 가격을 백업한다.
create table if not exists price_backup_20261102 as
  select sku, unit_price, fixed_dealer_price, discontinued, now() as backed_up_at
  from products;
alter table price_backup_20261102 enable row level security;

