-- 2) 데모 전용 604680: 소비자가 299,000원 기준 데모가(65% 할인) 95,100원 (10/14 파일 값)
update products set fixed_dealer_price = 95100 where sku = '604680';

-- 3) 검산 — 아래처럼 나오면 정상입니다:
--    600097 = 129000, 600165 = 28900, 18527 = 93900, 600556 = 469000, 604672 = 299000
--    604680 = 299000 (고정 딜러가 95100)
select p.sku, p.name, p.unit_price, p.fixed_dealer_price
from products p
where p.sku in ('600097', '600165', '18527', '600556', '604672', '604680')
order by p.sku;
